{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "The closest high-transfer analogue, [11C]PXT012253, a picolinamide heteroaryl amide, showed rapid and high brain uptake in non-human primate PET (peak SUV ~5 within 5 min), directly demonstrating that this picolinamide-anilide scaffold can achieve meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Picolinamide itself achieved 3180 ng/g brain concentration 1 h after 10 mg/kg oral dosing in rats with increased permeability, supporting CNS access for the shared picolinamide core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "A related methoxy-substituted benzamide anilide (DSM-RX78) was detected in rat brain after IV administration, indicating moderate BBB crossing and supporting the query's methoxy-anilide amide motif.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a neutral, low-TPSA picolinamide anilide with favorable passive permeability properties. Direct PET and brain-concentration evidence from close picolinamide analogues shows rapid or moderate brain uptake, and the physicochemical prior supports CNS access. Structurally distant poor-penetrant examples are not transferable because they lack the relevant amide/picolinamide features or contain ionizable acidic/basic groups absent in the query.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement for the exact query molecule.",
    "No explicit P-gp/BCRP efflux assay for the query; the amide and pyridine could still be transporter substrates.",
    "PET/tracer and single-timepoint data do not quantify unbound brain exposure or steady-state Kp,uu."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

